const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const http = require('node:http');
const { build } = require('esbuild');
const { chromium } = require('playwright');

// Local-only fixtures generated by test-card-onboarding.tsx. All checkout
// requests are intercepted; this test cannot create an account or use Stripe.
(async () => {
  const root = path.resolve('output/playwright');
  await build({
    stdin: { contents: `import React from 'react'; import { createRoot } from 'react-dom/client'; import { StartMembershipActions } from './src/app/start-membership/start-membership-actions';
      const node = document.getElementById('qa-actions');
      if (node) createRoot(node).render(React.createElement(StartMembershipActions, { confirming: location.pathname.includes('pending'), canceled: location.pathname.includes('canceled') }));`, resolveDir: process.cwd(), loader: 'tsx' },
    bundle: true, outfile: path.join(root, 'actions.js'), platform: 'browser', jsx: 'automatic',
    plugins: [{ name: 'offline-router', setup(b) {
      b.onResolve({ filter: /^next\/navigation$/ }, () => ({ path: 'router', namespace: 'offline' }));
      b.onLoad({ filter: /.*/, namespace: 'offline' }, () => ({ contents: 'export const useRouter = () => window.__fixtureRouter ||= { refresh() { window.__refreshes = (window.__refreshes || 0) + 1; } };', loader: 'js' }));
    } }],
  });
  const server = http.createServer((req, res) => {
    const name = new URL(req.url, 'http://localhost').pathname.slice(1);
    if (!/^[a-z-]+\.(html|css|js)$/.test(name)) { res.writeHead(404); res.end(); return; }
    try {
      let data = fs.readFileSync(path.join(root, name));
      if (name.endsWith('.html')) data = Buffer.from(data.toString().replace('</body>', '<script src="actions.js"></script></body>'));
      res.setHeader('Content-Type', name.endsWith('.css') ? 'text/css' : name.endsWith('.js') ? 'text/javascript' : 'text/html; charset=utf-8');
      res.end(data);
    } catch { res.writeHead(404); res.end(); }
  });
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  const base = `http://127.0.0.1:${server.address().port}`;
  let browser;
  try {
    browser = await chromium.launch({ channel: 'chrome', headless: true });
    const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
    const errors = [];
    page.on('pageerror', error => errors.push(error.message));
    await page.route('**/*', route => {
      assert.ok(route.request().url().startsWith(base), 'No external network in fixture QA');
      return route.continue();
    });
    await page.goto(`${base}/membership-required.html`);
    await page.getByRole('button', { name: /Continua con Pro Poi/ }).waitFor();
    assert.equal(await page.getByRole('heading', { name: 'Aggiungi la tua carta' }).count(), 1);
    await page.screenshot({ path: path.join(root, 'membership-desktop.png'), fullPage: true });
    let checkoutRequests = 0;
    await page.route('**/api/stripe/checkout', async route => {
      checkoutRequests++;
      assert.equal(route.request().method(), 'POST');
      assert.deepEqual(route.request().postDataJSON(), { tier: 'pro' });
      await route.fulfill({ status: 503, contentType: 'application/json', body: JSON.stringify({ message: 'Stripe non disponibile. Riprova.' }) });
    });
    await page.getByRole('button', { name: /Continua con Pro Poi/ }).click();
    await page.getByRole('alert').waitFor();
    assert.match(await page.getByRole('alert').innerText(), /Stripe non disponibile/);
    assert.equal(checkoutRequests, 1);
    assert.equal(await page.getByRole('button', { name: /Continua con Pro Poi/ }).isEnabled(), true);
    await page.goto(`${base}/membership-canceled.html`);
    assert.match(await page.getByRole('status').innerText(), /carta resta obbligatoria/);
    await page.screenshot({ path: path.join(root, 'membership-canceled.png'), fullPage: true });
    await page.clock.install();
    await page.goto(`${base}/membership-pending.html`);
    await page.waitForFunction(() => !!window.__fixtureRouter);
    await page.clock.runFor(61000);
    assert.equal(await page.evaluate(() => window.__refreshes), 20);
    assert.match(await page.getByRole('status').innerText(), /non è ancora arrivata/);
    await page.screenshot({ path: path.join(root, 'membership-pending.png'), fullPage: true });
    await page.reload();
    assert.match(await page.getByRole('status').innerText(), /Attendiamo la conferma/);
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto(`${base}/membership-required.html`);
    assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), true, 'No mobile horizontal overflow');
    await page.screenshot({ path: path.join(root, 'membership-mobile.png'), fullPage: true });
    await page.setViewportSize({ width: 1600, height: 1050 });
    await page.goto(`${base}/admin-readiness.html`);
    assert.equal(await page.getByText('Profilo / Billing', { exact: true }).count(), 1);
    assert.ok(await page.getByText('3/3', { exact: true }).count() > 0);
    assert.ok(await page.getByText('Non completato', { exact: true }).count() > 0);
    assert.ok(await page.getByText('In verifica', { exact: true }).count() > 0);
    await page.screenshot({ path: path.join(root, 'admin-readiness.png'), fullPage: true });
    assert.deepEqual(errors, []);
    console.log('PASS browser: desktop/mobile layout, checkout request/error recovery, cancellation, pending verification polling/timeout/refresh, truthful admin; five screenshots; no external requests.');
  } finally {
    if (browser) await browser.close();
    await new Promise(resolve => server.close(resolve));
  }
})().catch(error => { console.error(error); process.exitCode = 1; });
